import { v4 as uuid } from 'uuid'
import type { AxiosRequestConfig } from 'axios'
import { get, post, put } from '../base'
import type { CharacterVoiceModel, GenerateCharacterDefaultAvatarPayload, UpdateCharacterPayload } from '@/types/character'
import type { Character } from '@/types'

interface SearchQuery {
  query: string
  pageNum: number
  pageSize: number
}

interface SearchResult {
  pageNum: number
  totalCount: number
  chars: Character[]
}

class CharacterService {
  async search({ query, pageNum, pageSize }: SearchQuery) {
    return get<SearchResult>(`/char/search?pageNum=${pageNum}&pageSize=${pageSize}&query=${query}`)
  }

  async searchCharByName(name: string) {
    return get<Character | null>(`/char/searchCharByName?charName=${name}`)
  }

  async fetchVoiceById(voiceId: number) {
    return get<CharacterVoiceModel>(`/voice/getVoiceById?voiceId=${voiceId}`)
  }

  async updateCharacter(payload: UpdateCharacterPayload) {
    return put<Character>('/char/updateCharInfoByCharId', payload)
  }

  async getCharacterById(charId: number) {
    return get<Character>(`/char/getCharInfoById?charId=${charId}`)
  }

  async presignAvatarUrl(fileName: string) {
    return post<{
      presignedUrl: string
      s3Prefix: string
    }>('/s3/generatePresignedUrl', {
      fileName: `userUpload/characterName/${uuid()}-${fileName}`,
      method: 'put_object',
    })
  }

  async presignBackgroundUrl(fileName: string) {
    return post<{
      presignedUrl: string
      s3Prefix: string
    }>('/s3/generatePresignedUrl', {
      fileName: `userUpload/background/${uuid()}-${fileName}`,
      method: 'put_object',
    })
  }

  async uploadImage(presignedUrl: string, file: File) {
    return put<{
      presignedUrl: string
    }>(presignedUrl, file, {
      ignoreAuth: true,
    })
  }

  async generateCharacterDefaultAvatar(
    payload: GenerateCharacterDefaultAvatarPayload,
    config?: AxiosRequestConfig<any>,
  ) {
    return post<{
      presignedUrl: string
      s3Prefix: string
    }>('/char/generatePose', payload, config)
  }
}

export const characterService = new CharacterService()
